  "content": "1: //! Editor area - manages multiple editor panes, tabs, and split views
2: //!
3: //! This module implements a hierarchical layout system for multiple editor panes,
4: //! tabs, and split views, allowing the same document to be viewed in multiple places.
5: 
6: use std::collections::HashMap;
7: 
8: use super::document::Document;
9: use super::editor::EditorState;
10: 
11: // ============================================================================
12: // Identifiers
13: // ============================================================================
14: 
15: /// Unique identifier for a document
16: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
17: pub struct DocumentId(pub u64);
18: 
19: /// Unique identifier for an editor view
20: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
21: pub struct EditorId(pub u64);
22: 
23: /// Unique identifier for an editor group (pane)
24: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
25: pub struct GroupId(pub u64);
26: 
27: /// Unique identifier for a tab
28: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
29: pub struct TabId(pub u64);
30: 
31: // ============================================================================
32: // Layout Primitives
33: // ============================================================================
34: 
35: /// Rectangle for layout calculations
36: #[derive(Debug, Clone, Copy, Default)]
37: pub struct Rect {
38:     pub x: f32,
39:     pub y: f32,
40:     pub width: f32,
41:     pub height: f32,
42: }
43: 
44: impl Rect {
45:     pub fn new(x: f32, y: f32, width: f32, height: f32) -> Self {
46:         Self {
47:             x,
48:             y,
49:             width,
50:             height,
51:         }
52:     }
53: 
54:     pub fn contains(&self, px: f32, py: f32) -> bool {
55:         px >= self.x && px < self.x + self.width && py >= self.y && py < self.y + self.height
56:     }
57: }
58: 
59: // ============================================================================
60: // Tabs
61: // ============================================================================
62: 
63: /// A tab represents an open editor in a group
64: #[derive(Debug, Clone)]
65: pub struct Tab {
66:     pub id: TabId,
67:     pub editor_id: EditorId,
68:     pub is_pinned: bool,
69:     pub is_preview: bool, // Preview tabs get replaced on next file open
70: }
71: 
72: // ============================================================================
73: // Editor Group (pane with tabs)
74: // ============================================================================
75: 
76: /// An editor group contains a tab bar and displays one editor at a time
77: #[derive(Debug, Clone)]
78: pub struct EditorGroup {
79:     pub id: GroupId,
80:     pub tabs: Vec<Tab>,
81:     pub active_tab_index: usize,
82:     /// Layout info (set by parent during layout computation)
83:     pub rect: Rect,
84: }
85: 
86: impl EditorGroup {
87:     /// Get the currently active tab
88:     pub fn active_tab(&self) -> Option<&Tab> {
89:         self.tabs.get(self.active_tab_index)
90:     }
91: 
92:     /// Get the editor ID of the active tab
93:     pub fn active_editor_id(&self) -> Option<EditorId> {
94:         self.active_tab().map(|t| t.editor_id)
95:     }
96: }
97: 
98: // ============================================================================
99: // Layout Tree
100: // ============================================================================
101: 
102: /// Direction for splitting editor groups
103: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
104: pub enum SplitDirection {
105:     /// Children arranged left-to-right
106:     Horizontal,
107:     /// Children arranged top-to-bottom
108:     Vertical,
109: }
110: 
111: /// A container that splits space between children
112: #[derive(Debug, Clone)]
113: pub struct SplitContainer {
114:     pub direction: SplitDirection,
115:     pub children: Vec<LayoutNode>,
116:     /// Proportional sizes (0.0 to 1.0, must sum to 1.0)
117:     pub ratios: Vec<f32>,
118:     /// Minimum size in pixels for each child
119:     pub min_sizes: Vec<f32>,
120: }
121: 
122: /// A node in the layout tree - either a group or a split container
123: #[derive(Debug, Clone)]
124: pub enum LayoutNode {
125:     Group(GroupId),
126:     Split(SplitContainer),
127: }
128: 
129: // ============================================================================
130: // Editor Area (top-level container)
131: // ============================================================================
132: 
133: /// The editor area manages all groups, documents, and the layout tree
134: #[derive(Debug, Clone)]
135: pub struct EditorArea {
136:     /// All open documents (shared across editors)
137:     pub documents: HashMap<DocumentId, Document>,
138: 
139:     /// All editor states (each references a document)
140:     pub editors: HashMap<EditorId, EditorState>,
141: 
142:     /// All editor groups (each contains tabs)
143:     pub groups: HashMap<GroupId, EditorGroup>,
144: 
145:     /// The layout tree root
146:     pub layout: LayoutNode,
147: 
148:     /// Currently focused group
149:     pub focused_group_id: GroupId,
150: 
151:     /// ID generators
152:     next_document_id: u64,
153:     next_editor_id: u64,
154:     next_group_id: u64,
155:     next_tab_id: u64,
156: }
157: 
158: impl EditorArea {
159:     /// Create a new editor area with a single document and editor.
160:     /// This is the migration path from the old single-pane architecture.
161:     pub fn single_document(mut document: Document, mut editor: EditorState) -> Self {
162:         let doc_id = DocumentId(1);
163:         let editor_id = EditorId(1);
164:         let group_id = GroupId(1);
165:         let tab_id = TabId(1);
166: 
167:         // Assign IDs to document and editor
168:         document.id = Some(doc_id);
169:         editor.id = Some(editor_id);
170:         editor.document_id = Some(doc_id);
171: 
172:         let mut documents = HashMap::new();
173:         let mut editors = HashMap::new();
174:         let mut groups = HashMap::new();
175: 
176:         documents.insert(doc_id, document);
177:         editors.insert(editor_id, editor);
178: 
179:         let tab = Tab {
180:             id: tab_id,
181:             editor_id,
182:             is_pinned: false,
183:             is_preview: false,
184:         };
185: 
186:         groups.insert(
187:             group_id,
188:             EditorGroup {
189:                 id: group_id,
190:                 tabs: vec![tab],
191:                 active_tab_index: 0,
192:                 rect: Rect::default(),
193:             },
194:         );
195: 
196:         Self {
197:             documents,
198:             editors,
199:             groups,
200:             layout: LayoutNode::Group(group_id),
201:             focused_group_id: group_id,
202:             next_document_id: 2,
203:             next_editor_id: 2,
204:             next_group_id: 2,
205:             next_tab_id: 2,
206:         }
207:     }
208: 
209:     /// Get the currently focused group
210:     pub fn focused_group(&self) -> Option<&EditorGroup> {
211:         self.groups.get(&self.focused_group_id)
212:     }
213: 
214:     /// Get the currently focused group mutably
215:     pub fn focused_group_mut(&mut self) -> Option<&mut EditorGroup> {
216:         self.groups.get_mut(&self.focused_group_id)
217:     }
218: 
219:     /// Get the editor ID of the focused group's active tab
220:     pub fn focused_editor_id(&self) -> Option<EditorId> {
221:         self.focused_group().and_then(|g| g.active_editor_id())
222:     }
223: 
224:     /// Get the focused editor state
225:     pub fn focused_editor(&self) -> Option<&EditorState> {
226:         self.focused_editor_id()
227:             .and_then(|id| self.editors.get(&id))
228:     }
229: 
230:     /// Get the focused editor state mutably
231:     pub fn focused_editor_mut(&mut self) -> Option<&mut EditorState> {
232:         let editor_id = self.focused_editor_id()?;
233:         self.editors.get_mut(&editor_id)
234:     }
235: 
236:     /// Get the document ID of the focused editor
237:     pub fn focused_document_id(&self) -> Option<DocumentId> {
238:         self.focused_editor().and_then(|e| e.document_id)
239:     }
240: 
241:     /// Get the focused document
242:     pub fn focused_document(&self) -> Option<&Document> {
243:         self.focused_document_id()
244:             .and_then(|id| self.documents.get(&id))
245:     }
246: 
247:     /// Get the focused document mutably
248:     pub fn focused_document_mut(&mut self) -> Option<&mut Document> {
249:         let doc_id = self.focused_document_id()?;
250:         self.documents.get_mut(&doc_id)
