375:     /// Recursively search for group at point
376:     fn group_at_point_node(&self, node: &LayoutNode, x: f32, y: f32) -> Option<GroupId> {
377:         match node {
378:             LayoutNode::Group(group_id) => {
379:                 if let Some(group) = self.groups.get(group_id) {
380:                     if group.rect.contains(x, y) {
381:                         return Some(*group_id);
382:                     }
383:                 }
384:                 None
385:             }
386:             LayoutNode::Split(container) => {
387:                 for child in &container.children {
