2020: fn remove_group_from_layout(layout: &mut LayoutNode, group_id: GroupId) -> bool {
2021:     match layout {
2022:         LayoutNode::Group(id) => {
2023:             // Can't remove at this level - parent needs to handle it
2024:             *id == group_id
