2047:                 // Normalize ratios
2048:                 let sum: f32 = container.ratios.iter().sum();
2049:                 if sum > 0.0 {
2050:                     for ratio in &mut container.ratios {
2051:                         *ratio /= sum;
2052:                     }
2053:                 }
2054: 
2055:                 // If only one child remains, collapse the split
2056:                 if container.children.len() == 1 {
